// Format currency in INR (₹) representation
const formatINR = (val) => (Number(val || 0) < 0 ? '-₹' : '₹') + Math.abs(Number(val || 0)).toLocaleString('en-IN', { maximumFractionDigits: 2 });

const digest = $input.first().json;
const { period, user, summary, largestExpense, topCategories, budgetAlerts } = digest;

// Construct email / notification subject
const subject = `Weekly Financial Digest (${period.startDate} to ${period.endDate}) - ${user.name}`;

// Construct human-readable digest text
let text = `📊 WEEKLY FINANCIAL DIGEST\n`;
text += `Period: ${period.startDate} to ${period.endDate} (${period.days} days)\n`;
text += `Account: ${user.name} (${user.currency})\n`;
text += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
text += `💰 SUMMARY\n`;
text += `• Total Income:    ${formatINR(summary.totalIncome)}\n`;
text += `• Total Expenses:  ${formatINR(summary.totalExpenses)}\n`;
text += `• Net Savings:     ${formatINR(summary.netSavings)}\n`;
text += `• Transactions:    ${summary.transactionCount}\n`;

if (largestExpense) {
  text += `\n🏷️ LARGEST EXPENSE\n`;
  text += `• Merchant: ${largestExpense.merchant}\n`;
  text += `• Amount:   ${formatINR(largestExpense.amount)}\n`;
  text += `• Category: ${largestExpense.category}\n`;
  text += `• Date:     ${largestExpense.date}\n`;
} else {
  text += `\n🏷️ LARGEST EXPENSE: None recorded this week\n`;
}

text += `\n📂 SPENDING BY CATEGORY\n`;
if (Array.isArray(topCategories) && topCategories.length > 0) {
  topCategories.forEach((cat, idx) => {
    text += `${idx + 1}. ${cat.category.padEnd(14)} ${formatINR(cat.amount).padStart(10)}  (${cat.percentageOfSpend.toFixed(1)}%)\n`;
  });
} else {
  text += `No expense transactions recorded during this period.\n`;
}

text += `\n⚠️ BUDGET ALERTS (${period.endDate.slice(0, 7)})\n`;
if (Array.isArray(budgetAlerts) && budgetAlerts.length > 0) {
  budgetAlerts.forEach((alert) => {
    const badge = alert.status === 'exceeded' ? '🚨 EXCEEDED' : '⚠️ WARNING ';
    text += `[${badge}] ${alert.category}: ${formatINR(alert.spent)} / ${formatINR(alert.monthlyLimit)} (${alert.percentageUsed.toFixed(1)}% used)\n`;
  });
} else {
  text += `All monthly budgets are healthy (< 80% used).\n`;
}

text += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
text += `Generated automatically by Personal Finance Copilot`;

return [{
  json: {
    subject,
    text,
    period,
    user,
    summary,
    largestExpense,
    topCategories,
    budgetAlerts,
    generatedAt: new Date().toISOString()
  }
}];
